) AS (
  VALUES 
    (728::BIGINT, 'Sumamente desordenada. No atiende a consultas, correos, ni mensajes y regresa la retroalimentación de proyectos con semanas de retraso. Genera problemas con las fechas de entrega, sus examenes son innecesariamente complejos y no acepta reclamos.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-01-02T00:00:00+00:00'::TIMESTAMPTZ, '5a8059d2f69c4e14bce1be4abe77f50cc22fbe7ef3875e6bb1282c0cf3fe4b42'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'La profesora sabe mucho sobre el tema, solo que sí es necesario estudiar demasiado para algunas preguntas que realiza. Importante asistir a clases porque SIEMPRE va a hacer preguntas de temas random que mencione en la clase'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'ad7fa2f3cd3adf374e2bb4f7fb780a1d27b58d0a1cffdfc9b9822bc9e390ca9f'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Triple C es el terror de los estudiantes ya que pregunta por puntos y comas de sus presentaciones de 3 horas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-05-23T00:00:00+00:00'::TIMESTAMPTZ, '0ab00d7042a8461f4009a095fd774db8848a1b124354da5d94ef3a6b988df35d'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Bioquímica es de esos cursos de la carrera que son difíciles por naturaleza. La profesora es muy versada en el tema y le gusta el curso muchísimo, pero si espera mucho de uno y los exámenes son difíciles. No es mala, tan solo es estricta y exigente. Da puntos extra y ayuda con quiz. Explica bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'cfc7b3e17b9e72e4339840e5ad89146539c73dcd9b8ce1c9831cc0cb89d0d533'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Prepárense para "nunca" tener la razón, para que les exigan como estudiantes pero que ella haga lo que le dé la gana... pero al menos se aprende bien sobre el contenido del curso (masomenos) ????????????'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-30T00:00:00+00:00'::TIMESTAMPTZ, '4b2fffb11028b92cda42cad81f29fa276353322bfe7ecdf06a0d885df3b131c8'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La profesora es muy conocida en el tema, de hecho es una excelente y muy experimentada profesora. Pero es estricta, exigente y necesitas poner atencion. No es mal intencionada, pero al ser TAN inteligente ella espera muchisimo de uno. Estudie.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '38598eb522695198a70dfbcbe3b50e13e1292a8d6c438b29b765a9c12c5bed5e'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La profe al inicio del curso habla sobre temas que vieron los estudiantes en el curso de génetica y puede llegar a ser confuso para entender lo que se ve en la materia si se habla sobre genética, califica duro en quices y deja poco tiempo para realizarlos, pero intenta traer invitados para charlas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a0f1d6656ba635dbb146e45cb2868fe66b3d7b6c9f668747eea5a00baab67f71'::TEXT, ARRAY[3259]::BIGINT[]),
    (728::BIGINT, 'Si pueden evítenla, es bastante exigente, los quizes valen mucho y preguntan literalmente de todo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ff4fa8460123bd11db8fec17131655ab2b33332e4be056202433f5e9b5bfa3b3'::TEXT, ARRAY[3259]::BIGINT[]),
    (728::BIGINT, 'Explica relativamente bien pero casi no ayuda si se tienen dudas y las evaluciones son difíciles y preguntas mal redactadas y largas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd41a2d343614d1c1080e01886b7942a2ea19cc6d9b430cc6f4aac2cb74fc7c64'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Es estricta, califica en base a puntos muy específicos y sus clases son aburridas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-03-12T00:00:00+00:00'::TIMESTAMPTZ, '48d502ba58dc04201fa85dbe7f5dc996235789d49735d1e8a8b958845c6fae37'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'El curso en sí tiene muchos contenidos y son bastante profundos, entonces se ve mucha materia. Por eso las clases son muy largas, pero la profe lo explica muy bien. Simplemente hay que dedicar bastante tiempo para estudiar porque es complejo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2023-12-25T00:00:00+00:00'::TIMESTAMPTZ, '229a689737d20d7b79720dec702c70344b1381fc5c837b1feea9607bad8a7bcc'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Tiende a calificar de una manera muy estricta aunque sus clases sean buenas sirven de poco en el tipo de evaluación que utiliza, ya que requiere que el estudiante memorice aspectos pequeños y específicos de metabolismos que por si solos ya son complicados.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, '30182042cd2239274ca2823b72bd9dbc26e0a828f4bd5629b2a0f1823e596fb5'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Calificaiones dificiles, clases muy interesantes , ademas de eso no deja mucho trabajo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-26T00:00:00+00:00'::TIMESTAMPTZ, 'd6e63043e4b8c27fbc8c1301ad758ca9e549a83d6b0ee749822374cdcf46c8f0'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Su clase esta muy bien planteada. Se entiende lo que quiere decir si uno le pone atención. Gran conocimiento e interés por la materia del curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-03T00:00:00+00:00'::TIMESTAMPTZ, '6d1d3ff5f3f555c6977b2c895b8388ba6c59996e2135e0ad9d2930fe4e49a894'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Se nota su conocimiento, pero no tiene el carácter de una profesora, es poco paciente y desconfía mucho del aprendizaje de los estudiantes, por lo que tiende a hacer evaluaciones difíciles con muy poco tiempo para resolverlas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, '1716728c06966aa9e89493b060a85cae8175685d298c9641a0557713e6bbdc9d'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Es una profe que sabe MUCHO y se nota el nivel de experiencia que tiene. Explicando no es la mejor pero tampoco la peor. Sus exámenes son complicados, largos y da poco tiempo, además de meter cosas que ni ella explicó en clase. Lo malo es su falta de empatía y ayuda al estudiante'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '88d1debf90dbcb8ad024256e4cb98486009b2caa869a477a3b900760691040d4'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Grosera y desconsiderada. La forma que tiene de explicar es confusa. Poco tiempo para realizar las evaluaciones y hace preguntas largas,.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4de2b25813682fc28cf1123ef28244662832761ae8a89d1e549b13bbeca6bc3a'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La profesora es excelente y posee demasiado conocimiento; sus exámenes suelen utilizar una metodología en la cual aplicamos los conocimientos adquiridos en clase a casos específicos que se nos presentan en la evaluación, lo cual podría llegar a percibirse como complicado, pero nos prepara mejor.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c6c2b021eeb955a4a67fe22d79946c0f0d5ee3712e2722ef810ddb6b0c9a64ed'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La forma en la que explica es a veces confuso porque usa metáforas que, para empeorar, las evalúa en el examen. Es poco comprensiva con las situaciones de los estudiantes y da muy muy poco tiempo para resolver las evaluaciones.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e48760a3cf4d2812240055dfa4f5bf8474827050584366d0fd8df9424adb2751'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'sin mucho qué decir, zzzzzzzz'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c057187f5f76f77113d9d771fbf06adcbd6f8febd9d0ff15d693ff5fdee43171'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Sus clases no son malas, pero la forma en que evalúa es absurda y muchas veces tiene mala actitud.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0db4f03520e174062383d56cebcf47e6a09cae683ffb76cb8badc782aab8cfcc'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Molesta bastante que le den cursos importantes a un profesor tan malo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'b27b529315f1751f0257e17ec4ae4dc21c84e7e2f9211f22855e4f3d015d1c7c'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Califica cosas que no se ven para nada en clase, y deja muy poco tiempo para las evaluaciones, son preguntas muy largas y el tiempo no alcanza ni para la mitad'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-05T00:00:00+00:00'::TIMESTAMPTZ, '17c401bfdf91778e4d30488e6a4b61875c8343c93ce29a2b2719193b6b839029'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Pregunta en los exámenes como si ella fuera buena enseñando, lo cual no pasa. Aunque, su principal problema es que la ayuda que brinda frente a consultas es nula.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'd7db0c2a618c83fb78595fc0e40f7b6c4835913a00c3441a4c515bbc6ee370ed'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Es buena explicando, pero no considero que tenga lo necesario para ser profesora, califica demasiado duro preguntas que están mal planteadas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2023-05-01T00:00:00+00:00'::TIMESTAMPTZ, '92096ed02d07abfc7e0e6305d43a389d68c98ea450dd121219e88de93f6d1e64'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Las clases son claras y se entienden con facilidad, aunque califica con tecnicismos y detalles que no explica bien. No es nada amable con el estudiante y no acepta reclamos o simplemente no responde a estos. No está para el estudiante y no le ayuda en su proceso. Es irresponsable con el estudiante.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '18f1349ffc3df4cd90ed06dd10aa27f261f79067d70a0d98020a06244a0d1c2a'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'La clase bien explicada pero a la hora de los quices y exámenes pregunta de forma super detallada cosas que se vieron superficialmente. Es quisquillosa, nunca se le queda bien, grosera. Cuesta que conteste los correos, da la retroalimentación tarde. Un dolor de cabeza'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '4694d8fdf62963e7481c6b913d04e6005dfe5cf80bd33158c6ed51b4f3fc12c1'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Explica bien en clases y se le entiende bastante bien. Pero aveces llega a ser súper grosera con los estudiantes, no tolera nada y no tiene empatía por los estudiantes. Las horas de consulta no las aplica, y quices como examen da poco tiempo y pone materia que nunca vimos y difícil'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'e0490694e055a4bc80ac0f35634a2bb2f9618968b7177830fb1757ff13f7f6ad'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'PESIMA profesora. Es un DOLOR, da pesima retroalimentacion es demasado grosera, incomprensiva no es congruente con lo que evalua a lo visto en clase'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-10-14T00:00:00+00:00'::TIMESTAMPTZ, '311038c05ca2f40c89b481276ff1648de895b44aa9fdfb86bdb079cb424057a0'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'En intro a biotec cuando daba la clase super clara, a la hora de quices, eran algo confusos los items, cuando se lepreguntaba algo postergaba mucho las dudas porque pasa muy ocupada, pero muy amable'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '43551dce9d51e492afcf994e468ac54c3af2fab8f5ce0ab7f723c9b26776eea2'::TEXT, ARRAY[3259]::BIGINT[]),
    (728::BIGINT, 'Es excelente profe, es demasiado buena explicando y hace que las clases sean interesantes y que uno se motive. Hay que estudiar bastante para los quices ya que, califica un poco duro y da poco tiempo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '72e1dbce809515d5dbe8a4cb287c96cb39cc61fca8edfff617e393eba8f4546b'::TEXT, ARRAY[3259]::BIGINT[]),
    (728::BIGINT, 'Da el curso con Laura, pero Caro es mucho más cómica y hasta cierto punto brinda confianza. Sin embargo, el curso es difícil así que no se confíe. Le gusta que participe mucho en clase (llama por nombre). Igual opino que dan poco tiempo para resolver exámenes y quices así que vaya muy preparadx.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Da crédito extra']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '625ca846bfc47452143f7aada8051e799fcc8ae3a1b54fbaad896248005dda26'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'El curso de por sí es denso, pero muy interesante. Solo que la forma en la que lo evalúan desmotiva. Los exámenes son difíciles y con muy poco tiempo para resolverlos, asigna muchas lecturas (como si uno no llevara más cursos). Da oportunidad de puntos extra pero de verdad hay que ganárselos.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'b3e4f9283b360c8c0d69fba70a8130d155e385663134ed62f921223eab9bf4ce'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La profe es buena gente y hasta cierto punto es comprensiva con el estudiante (puede llegar a aplazar fechas de entrega) pero los exámenes son difíciles y califica duro (pero el curso como tal es difícil). Muchas veces hay que esperar para que le responda las consultas pero sí le responde.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '391eb50b30197045538747c8bf144fa72daba9834fed0597695a544dde7a9c80'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'El curso en si es muy duro y desgastante, sin embargo la profe es directa con la materia y le gusta que se participe en clase, deja alguna que otra lectura, pero con las presentaciones se estudia. Da crédito extra y le interesa que el estudiante realice todas las asignaciones.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'f812b37e8595dc447abd6a15283a9fc2cb495b08ce299451aa6d61a49e213c81'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'El curso por si solo es difícil y denso pero la profe se esfuerza porque sea entendible. Los exámenes son algo difíciles y el tiempo es poco, da crédito extra.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '22eed58fde8652a030082cd9953b5e251aaa7153e330aa72da8ee821e293db11'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'La profe es muy buen persona y explica bien pero califica duro en los exámenes, además, da muy poco tiempo. La profe realiza actividades para puntos extra por lo que le ayudan bastante en la nota.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '177a8c7041a3e61b9c1c0cced81dca38c12ad3be56add3d5bbc3d2ff16aea6a5'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Los exámenes son complicados y da poco tiempo para resolverlos porque ella los considera sencillos. En las clases da bastantes ejemplos y se entienden bien si presta bastante atención. Si no pronuncia Hardy-Weinberg en alemán se esfuerza porque lo haga lol'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '29e8c80090b20c31cf7cf0bdc19c3056334f3ec023035cf15c09d032e82a8d7d'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Es una profesora super simpática y considerando que es un curso pesado le entendí muy bien la materia para el poco tiempo que se tenía, además daba ejemplos interesantes que lo ayudaban a uno a aprender mejor la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '4f37a098218b2eb1ad451ea8630a906bddca04b622bb43503bd9a924f095dcdf'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '27aeb8c2a28a238ae2a47843a6c4969c7a11fd028318d0fdb45fb98cee37d49d'::TEXT, ARRAY[3268]::BIGINT[]),
    (728::BIGINT, 'Pesima profesora, nunca daba instrucciones claras, subia las presentaciones tarde, dejaba trabajos para el dia antes del examen. No se puede hablar con ella, es muy cerrada. Si ella da el curso mejor no matricularlo.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-28T00:00:00+00:00'::TIMESTAMPTZ, '4117af173ba2ebba856beeb9dc07676612be87f5ce55785f43209c917cd06eda'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'La verdad la profe mejoró mucho en un semestre. Las clases las hizo muy chivas y explicó muy bien la materia, además se nota que le encanta enseñar Bioquímica. Hace muchos quices que sí son un poco difíciles, pero honestamente reestructuró el curso e hizo que valiera la pena. Realmente aprendí :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8b78ddbd98432bbc75c80bb4c925b87fe649d80f77c1ae414b30eaaa24ab953e'::TEXT, ARRAY[3274]::BIGINT[]),
    (728::BIGINT, 'Es muy pura vida, aunque sí es un poco exigente y difícil. En general trata de que uno se interese por la clase y aprenda. El único problema es que es un poco desordenada, pero igual ayuda cuando uno ocupa :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2019-07-25T00:00:00+00:00'::TIMESTAMPTZ, '43cc1574bb870a760874601c8e9fbd7f5dfab618b0b18d756a9b5354ee2138ca'::TEXT, ARRAY[3268]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
